(function(root){
const keys=['temperature','conductivity','pH','DO','turbidity'];
const flagNames={1:'QC passed',2:'Not evaluated',3:'Suspect',4:'Failed',9:'Missing data'};
const flagClasses={1:'pass',2:'unknown',3:'suspect',4:'fail',9:'missing'};
function stamp(s){return new Date(s+'+07:00').getTime()}
function aggregate(t){if(t.missing===9)return 9;return Math.max(2,...Object.values(t).filter(x=>x===3||x===4))===2?(Object.values(t).includes(1)?1:2):Math.max(...Object.values(t).filter(x=>x===3||x===4))}
function qcAt(rows,i,key,cursor){const q=rows[i].qc[key];if(i===cursor){const tests={...q.tests,spike:2};return {...q,tests,flag:aggregate(tests)}}return q}
function currentTwin(data,cursor){const row=data.rows[cursor],features={};for(const key of keys){let good=null;for(let j=cursor;j>=0;j--){if(qcAt(data.rows,j,key,cursor).flag===1){good={value:data.rows[j].values[key],ts:data.rows[j].ts};break}}features[key]={properties:{observed:{value:row.values[key],ts:row.ts,unit:data.params[key].unit,qualityFlag:qcAt(data.rows,cursor,key,cursor).flag},last_good:good}}}features.health={properties:{mode:'historical-replay',sourceTime:row.ts,deviceError:row.error||null,depth_m:null,calibration_ref:null,unit_id:null,spikeStatus:'pending_next_observation',qcVersion:data.meta.qcVersion}};return {thingId:'aquatwin:nuoibien-2',attributes:{site:row.site,device:row.device,timezone:'UTC+07:00',sourceMapping:'salinity=conductivity_mS_cm'},features}}
function summary(data,cursor,subset){const counts={1:0,2:0,3:0,4:0,9:0};const arr=subset||data.rows.slice(0,cursor+1);for(const row of arr){const i=data.rows.indexOf(row);for(const k of keys)counts[qcAt(data.rows,i,k,cursor).flag]++}return counts}
function events(data,cursor){const result=[];for(let i=0;i<=cursor;i++){const r=data.rows[i];if(r.gapMinutes>30)result.push({id:r.id+'gap',i,kind:'gap',title:'Observation-stream interruption',detail:`No records for ${r.gapMinutes.toFixed(1)} minutes. No environmental conclusion is possible for this gap.`,flag:9});if(r.error){result.push({id:r.id+'error',i,kind:'device',title:'Unable to read device',detail:'The serial port is unavailable; all five parameters are missing.',flag:9});continue}for(const key of keys){const q=qcAt(data.rows,i,key,cursor);if(q.flag===3||q.flag===4){const reasons=Object.entries(q.tests).filter(([k,v])=>v===3||v===4).map(([k])=>({spike:'spike',rate_of_change:'rate of change',flat_line:'flat line',site_plausible:'outside provisional site range',gross_range:'outside QC range'})[k]);result.push({id:r.id+key,i,kind:key,title:`${data.params[key].label}: needs review`,detail:`${r.values[key]} ${data.params[key].unit} · ${reasons.join(', ')}. QC flags do not establish risk to fish.`,flag:q.flag})}}}return result.reverse()}
function backtest(data,key){const rows=data.rows;const split=Math.floor(rows.length*.7),pairs=[];for(let i=split;i<rows.length-1;i++){const r=rows[i],n=rows[i+1];if(r.values[key]==null||n.values[key]==null||r.error||n.error||n.gapMinutes>30||n.gapMinutes<=0)continue;const usable=q=>aggregate({...q.tests,spike:2})===1;if(!usable(r.qc[key])||!usable(n.qc[key]))continue;pairs.push({i,actual:n.values[key],prediction:r.values[key],elapsedMinutes:n.gapMinutes,error:n.values[key]-r.values[key]})}const count=pairs.length;if(!count)return {count:0};return {count,mae:pairs.reduce((s,p)=>s+Math.abs(p.error),0)/count,rmse:Math.sqrt(pairs.reduce((s,p)=>s+p.error*p.error,0)/count),bias:pairs.reduce((s,p)=>s-p.error,0)/count,start:rows[split].ts,end:rows.at(-1).ts,pairs}}
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const api={keys,flagNames,flagClasses,stamp,aggregate,qcAt,currentTwin,summary,events,backtest,escape};if(typeof module!=='undefined')module.exports=api;root.AquaCore=api;
})(typeof window==='undefined'?globalThis:window);
